pub fn start_transfer<B: RegBus>(bus: &mut B, addr: u32, len: u32) -> Result<(), SpecGap> {
    bus.write32(0x40, addr);
    bus.write32(0x44, len);
    bus.write32(0x00, 1);
    for _ in 0..100 {
        if bus.read32(0x10) & 1 != 0 {
            return Ok(());
        }
        bus.delay_us(1);
    }
    Err(SpecGap("transfer timed out"))
}

